#!/usr/bin/env python3
"""dock/protein_na_docking — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "protein_na_docking"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'protein_na_docking', 'receptor': '', 'ligand': '', 'best_affinity': 0.0, 'poses': [{'rank': 1, 'affinity_kcal_per_mol': 0.0, 'pose_path': ''}], 'runtime_sec': 0.0, 'diagnostics': {'brain': 'dock', 'archetype': 'docking'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """蛋白-核酸 docking:host_env=praxis-dock 自带 boltz,支持 protein + NA chain
    在同一 YAML/FASTA 输入里联合预测。

    输入:input_path (boltz yaml 含 protein + na chain) 或 protein_pdb + na_3d_pdb /
          na_sequence / sequence_specificity / expected_motif_or_PAM
    输出:complex_pdb / plddt_mean / ptm / iptm / na_sanity_pass / diagnostics

    Sanity:NA-specific docker 已满足(boltz 内部已对 NA 训练);PAM/PWM 校验留 future。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    input_path = payload.get("input_path") or payload.get("yaml") or payload.get("fasta")
    protein_pdb = payload.get("protein_pdb")
    na_sequence = payload.get("na_sequence")
    use_msa = bool(payload.get("use_msa_server", True))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="boltz_na_")

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "predictor": "boltz",
                   "sequence_specificity": payload.get("sequence_specificity"),
                   "expected_motif_or_PAM": payload.get("expected_motif_or_PAM"),
                   "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": protein_pdb or "", "ligand": na_sequence or "",
                "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}

    if not input_path:
        return {"ok": False, "error": "需要 input_path(boltz yaml/fasta 含 protein + NA chain)",
                "hint": "示例 YAML: sequences:[{protein: {id: A, sequence: 'MK...'}}, {dna: {id: B, sequence: 'ATGC...'}}]",
                "diagnostics": diagnostics}
    if not _os.path.isfile(input_path):
        return {"ok": False, "error": f"input_path 不存在: {input_path!r}", "diagnostics": diagnostics}

    cmd = ["boltz", "predict", input_path, "--out_dir", out_dir,
           "--output_format", "pdb"]
    if use_msa:
        cmd.append("--use_msa_server")
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"cmd": r.get("cmd")[:200], "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "boltz predict 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}

    import glob as _glob
    pdbs = sorted(_glob.glob(_os.path.join(out_dir, "**", "*.pdb"), recursive=True))
    best_pdb = pdbs[0] if pdbs else ""
    poses = [{"rank": i + 1, "affinity_kcal_per_mol": 0.0, "pose_path": p}
             for i, p in enumerate(pdbs[:9])]
    return {"ok": True, "skill_id": SKILL,
            "receptor": protein_pdb or "",
            "ligand": na_sequence or "",
            "best_affinity": 0.0,
            "poses": poses or [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": best_pdb}],
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
